// DP：dp[i] = s 的前 i 個字元能否被字典切分（直接比對每個單字）
// 時間複雜度: O(n · W · L)，空間複雜度: O(n)
bool wordBreak(char* s, char** wordDict, int wordDictSize) {
    int n = strlen(s);
    bool* dp = calloc(n + 1, sizeof(bool));
    int* lens = malloc(sizeof(int) * wordDictSize);
    for (int k = 0; k < wordDictSize; k++) lens[k] = strlen(wordDict[k]);
    dp[0] = true;

    for (int i = 1; i <= n; i++) {
        for (int k = 0; k < wordDictSize && !dp[i]; k++) {
            int len = lens[k];
            if (len <= i && dp[i - len] && strncmp(s + i - len, wordDict[k], len) == 0) {
                dp[i] = true;
            }
        }
    }
    bool ans = dp[n];
    free(dp);
    free(lens);
    return ans;
}

